import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"Dashboard","description":"Visual analytics and real-time statistics for captured HTTP traffic in NectoProxy.","frontmatter":{"title":"Dashboard","description":"Visual analytics and real-time statistics for captured HTTP traffic in NectoProxy."},"headers":[],"relativePath":"features/dashboard.md","filePath":"features/dashboard.md","lastUpdated":1772297611000}'),i={name:"features/dashboard.md"};function o(n,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The Dashboard provides a <strong>visual analytics view</strong> of your captured HTTP traffic. Real-time charts, statistical summaries, and top-level metrics give you a bird&#39;s-eye view of your application&#39;s network behavior, making it easy to spot patterns, anomalies, and performance issues.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The dashboard is organized into two main areas:</p><ol><li><strong>Statistical summary cards</strong> -- Key metrics at a glance</li><li><strong>Charts</strong> -- Visual representations of traffic data over time and by category</li></ol><p>All dashboard data updates <strong>in real time</strong> as new traffic is captured, so you can watch metrics evolve as you interact with your application.</p><h2 id="statistical-summary-cards" tabindex="-1">Statistical Summary Cards <a class="header-anchor" href="#statistical-summary-cards" aria-label="Permalink to &quot;Statistical Summary Cards&quot;">​</a></h2><p>The top of the dashboard displays summary cards with key metrics:</p><h3 id="total-requests" tabindex="-1">Total Requests <a class="header-anchor" href="#total-requests" aria-label="Permalink to &quot;Total Requests&quot;">​</a></h3><p>The total number of HTTP requests captured in the active session.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Total Requests</span></span>
<span class="line"><span>    1,247</span></span></code></pre></div><h3 id="average-response-time" tabindex="-1">Average Response Time <a class="header-anchor" href="#average-response-time" aria-label="Permalink to &quot;Average Response Time&quot;">​</a></h3><p>The mean response time across all captured requests, measured in milliseconds.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Avg Response Time</span></span>
<span class="line"><span>    342 ms</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A high average response time may indicate backend performance issues. Drill into the &quot;Top Slowest Requests&quot; chart to identify specific endpoints that are dragging the average up.</p></div><h3 id="error-rate" tabindex="-1">Error Rate <a class="header-anchor" href="#error-rate" aria-label="Permalink to &quot;Error Rate&quot;">​</a></h3><p>The percentage of requests that returned error status codes (4xx and 5xx) relative to total requests.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error Rate</span></span>
<span class="line"><span>    3.2%</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>An error rate above 1-2% typically warrants investigation. Check the &quot;Requests by Status Code&quot; chart to see whether errors are concentrated on specific status codes (e.g., a spike in 429 rate-limiting responses or 503 service unavailable errors).</p></div><h2 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h2><h3 id="requests-per-second" tabindex="-1">Requests Per Second <a class="header-anchor" href="#requests-per-second" aria-label="Permalink to &quot;Requests Per Second&quot;">​</a></h3><p>A <strong>time-series line chart</strong> showing the rate of requests over time. The x-axis represents time, and the y-axis shows the number of requests per second.</p><p><strong>What to look for:</strong></p><ul><li><strong>Spikes</strong> -- Sudden increases in request rate may indicate polling loops, retry storms, or user-initiated batch operations</li><li><strong>Drops</strong> -- Sudden decreases may indicate connectivity issues or blocked traffic</li><li><strong>Steady patterns</strong> -- Consistent request rates indicate normal application behavior</li></ul><details class="details custom-block"><summary>Example: Identifying a Polling Loop</summary><p>If you see a consistent high request rate (e.g., 10 requests per second) even when the application is idle, this likely indicates an aggressive polling interval. Look at the traffic list to identify which endpoint is being polled and consider reducing the frequency or switching to WebSocket for real-time updates.</p></details><h3 id="error-rate-over-time" tabindex="-1">Error Rate Over Time <a class="header-anchor" href="#error-rate-over-time" aria-label="Permalink to &quot;Error Rate Over Time&quot;">​</a></h3><p>A <strong>time-series chart</strong> showing the percentage of error responses (4xx and 5xx) over time. This helps you correlate error spikes with specific actions or time periods.</p><p><strong>What to look for:</strong></p><ul><li><strong>Error spikes after deployments</strong> -- Indicates a regression</li><li><strong>Gradual increase in errors</strong> -- May indicate resource exhaustion on the server</li><li><strong>Periodic error patterns</strong> -- Could indicate scheduled jobs or maintenance windows</li></ul><h3 id="response-time-histogram" tabindex="-1">Response Time Histogram <a class="header-anchor" href="#response-time-histogram" aria-label="Permalink to &quot;Response Time Histogram&quot;">​</a></h3><p>A <strong>histogram</strong> showing the distribution of response times across all captured requests. The x-axis shows response time buckets (e.g., 0-100ms, 100-200ms, etc.), and the y-axis shows the number of requests in each bucket.</p><p><strong>What to look for:</strong></p><ul><li><strong>Bimodal distribution</strong> -- Two clusters of response times may indicate cache hits vs. cache misses, or fast vs. slow database queries</li><li><strong>Long tail</strong> -- A few very slow requests dragging out the right side of the histogram indicate outlier performance issues</li><li><strong>Shift right</strong> -- If the entire distribution shifts to higher response times compared to a baseline, overall performance has degraded</li></ul><h3 id="requests-by-domain" tabindex="-1">Requests by Domain <a class="header-anchor" href="#requests-by-domain" aria-label="Permalink to &quot;Requests by Domain&quot;">​</a></h3><p>A <strong>bar chart</strong> or <strong>pie chart</strong> showing the distribution of requests across different domains (hostnames). This reveals which services your application communicates with most frequently.</p><p><strong>What to look for:</strong></p><ul><li><strong>Unexpected domains</strong> -- Third-party services you did not expect your application to contact</li><li><strong>Dominant domains</strong> -- One domain receiving a disproportionate number of requests may be a candidate for optimization (caching, batching, etc.)</li><li><strong>CDN vs. API traffic</strong> -- Understanding the ratio of static asset requests vs. API requests</li></ul><details class="details custom-block"><summary>Example: Discovering Unnecessary Requests</summary><p>A &quot;Requests by Domain&quot; chart might reveal that <code>analytics.thirdparty.com</code> accounts for 30% of all requests. This is a signal to investigate whether the analytics integration is overly chatty and could be optimized.</p></details><h3 id="requests-by-status-code" tabindex="-1">Requests by Status Code <a class="header-anchor" href="#requests-by-status-code" aria-label="Permalink to &quot;Requests by Status Code&quot;">​</a></h3><p>A <strong>bar chart</strong> showing how many requests returned each status code. Status codes are grouped and color-coded:</p><table tabindex="0"><thead><tr><th>Range</th><th>Color</th><th>Category</th></tr></thead><tbody><tr><td><strong>2xx</strong></td><td>Green</td><td>Successful responses</td></tr><tr><td><strong>3xx</strong></td><td>Blue</td><td>Redirections</td></tr><tr><td><strong>4xx</strong></td><td>Orange</td><td>Client errors</td></tr><tr><td><strong>5xx</strong></td><td>Red</td><td>Server errors</td></tr></tbody></table><p><strong>What to look for:</strong></p><ul><li><strong>High 301/302 count</strong> -- Excessive redirects can slow page loads</li><li><strong>High 404 count</strong> -- Broken links or missing assets</li><li><strong>Any 5xx responses</strong> -- Server errors that need investigation</li><li><strong>429 responses</strong> -- Rate limiting is being triggered</li></ul><h3 id="top-slowest-requests" tabindex="-1">Top Slowest Requests <a class="header-anchor" href="#top-slowest-requests" aria-label="Permalink to &quot;Top Slowest Requests&quot;">​</a></h3><p>A <strong>ranked list</strong> of the slowest requests captured in the session, ordered by response time (longest first).</p><table tabindex="0"><thead><tr><th>Rank</th><th>URL</th><th>Duration</th><th>Status</th></tr></thead><tbody><tr><td>1</td><td><code>POST /api/reports/generate</code></td><td>12,450 ms</td><td>200</td></tr><tr><td>2</td><td><code>GET /api/search?q=widgets</code></td><td>8,230 ms</td><td>200</td></tr><tr><td>3</td><td><code>GET /api/dashboard/analytics</code></td><td>5,120 ms</td><td>200</td></tr><tr><td>4</td><td><code>POST /api/images/upload</code></td><td>4,890 ms</td><td>201</td></tr><tr><td>5</td><td><code>GET /api/users?include=all</code></td><td>3,450 ms</td><td>200</td></tr></tbody></table><p><strong>What to look for:</strong></p><ul><li>Endpoints that consistently appear in this list are prime optimization targets</li><li>The difference between the slowest and average response time indicates how much variability exists</li><li>Check whether slow requests are slow due to server processing (high TTFB) or large responses (high download time)</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Click on any entry in the &quot;Top Slowest Requests&quot; list to jump to that request in the traffic list, where you can inspect its timing breakdown, headers, and response body in detail.</p></div><h2 id="real-time-updates" tabindex="-1">Real-Time Updates <a class="header-anchor" href="#real-time-updates" aria-label="Permalink to &quot;Real-Time Updates&quot;">​</a></h2><p>Dashboard charts and statistics update <strong>in real time</strong> as new traffic flows through NectoProxy. You do not need to refresh or reload the dashboard.</p><p>This real-time behavior is useful for:</p><ul><li><strong>Monitoring live testing</strong> -- Watch metrics evolve as you interact with your application</li><li><strong>Observing the impact of changes</strong> -- Deploy a fix and immediately see the effect on error rates or response times</li><li><strong>Detecting anomalies</strong> -- Spot unusual patterns (spikes, drops, errors) as they happen</li></ul><h2 id="filtering-dashboard-data" tabindex="-1">Filtering Dashboard Data <a class="header-anchor" href="#filtering-dashboard-data" aria-label="Permalink to &quot;Filtering Dashboard Data&quot;">​</a></h2><p>The dashboard displays data from the <strong>active session</strong>. To change what data is displayed:</p><h3 id="by-session" tabindex="-1">By Session <a class="header-anchor" href="#by-session" aria-label="Permalink to &quot;By Session&quot;">​</a></h3><p>Switch to a different <a href="./sessions.html">session</a> to view that session&#39;s dashboard metrics. This lets you compare dashboard views across different test runs.</p><h3 id="by-time-range" tabindex="-1">By Time Range <a class="header-anchor" href="#by-time-range" aria-label="Permalink to &quot;By Time Range&quot;">​</a></h3><p>If the session contains a large amount of traffic, you can narrow the dashboard to a specific time range:</p><ul><li><strong>Last 5 minutes</strong></li><li><strong>Last 15 minutes</strong></li><li><strong>Last 1 hour</strong></li><li><strong>All time</strong> (entire session)</li></ul><h3 id="by-domain-or-path" tabindex="-1">By Domain or Path <a class="header-anchor" href="#by-domain-or-path" aria-label="Permalink to &quot;By Domain or Path&quot;">​</a></h3><p>Filter dashboard data to show metrics for a specific domain or URL path:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Filter: api.example.com</span></span></code></pre></div><p>This recalculates all charts and statistics using only traffic to the specified domain.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="performance-monitoring" tabindex="-1">Performance Monitoring <a class="header-anchor" href="#performance-monitoring" aria-label="Permalink to &quot;Performance Monitoring&quot;">​</a></h3><p>Use the dashboard to monitor your application&#39;s network performance during development:</p><ol><li>Start a new session for your performance testing</li><li>Interact with your application (or run automated tests)</li><li>Watch the dashboard for response time trends and error rates</li><li>Use the &quot;Top Slowest Requests&quot; to identify optimization targets</li><li>Make changes and re-test, comparing dashboard metrics between sessions</li></ol><h3 id="deployment-verification" tabindex="-1">Deployment Verification <a class="header-anchor" href="#deployment-verification" aria-label="Permalink to &quot;Deployment Verification&quot;">​</a></h3><p>After deploying a new version:</p><ol><li>Create a new session for post-deployment monitoring</li><li>Drive traffic through the application</li><li>Check the error rate for any increase compared to pre-deployment</li><li>Verify that response times have not degraded</li><li>Look for any unexpected changes in the domain or status code distributions</li></ol><h3 id="load-pattern-analysis" tabindex="-1">Load Pattern Analysis <a class="header-anchor" href="#load-pattern-analysis" aria-label="Permalink to &quot;Load Pattern Analysis&quot;">​</a></h3><p>Understand your application&#39;s communication patterns:</p><ol><li>Capture traffic from a realistic user session</li><li>Review the &quot;Requests by Domain&quot; chart to see which services are called</li><li>Review the &quot;Requests Per Second&quot; chart to understand traffic patterns</li><li>Identify opportunities for optimization (batching, caching, reducing unnecessary calls)</li></ol><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Dashboard data is computed from the traffic entries in the active session. Clearing the session or switching to a different session resets the dashboard view. Export sessions before clearing them if you want to preserve the data for future reference.</p></div>`,76)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
